class RecordOwner:
    def __init__(self):
        self.records = {}
        self.open_count = 0

    def start(self, key, value):
        self.records[key] = {"value": value, "state": "open"}
        self.open_count += 1

    def stop(self, key):
        record = self.records.pop(key)
        self.open_count -= 1
        return {**record, "state": "closed"}


class RecordReaper:
    def __init__(self):
        self.records = {}
        self.open_count = 0

    def adopt(self, key, value):
        self.records[key] = {"value": value, "state": "open"}
        self.open_count += 1

    def expire(self, key):
        record = self.records.pop(key)
        self.open_count -= 1
        return {**record, "state": "expired"}


